add_filter( 'the_content', 'perfectpixel_related_products_in_posts', 20 );

function perfectpixel_related_products_in_posts( $content ) {
	if ( ! is_singular( 'post' ) || ! in_the_loop() || ! is_main_query() ) {
		return $content;
	}
	$tags = wp_get_post_tags( get_the_ID(), array( 'fields' => 'slugs' ) );
	if ( ! $tags ) {
		return $content;
	}
	$limit = min( 12, max( 1, (int) '{{post_products_limit}}' ) );
	$ids   = wc_get_products( array( 'status' => 'publish', 'tag' => $tags, 'limit' => $limit, 'return' => 'ids', 'visibility' => 'catalog' ) );
	if ( ! $ids ) {
		return $content;
	}
	$grid = do_shortcode( sprintf( '[products ids="%s" columns="%d"]', esc_attr( implode( ',', $ids ) ), min( 4, $limit ) ) );
	return $content . '<section class="perfectpixel-post-products"><h2>' . esc_html( '{{post_products_heading}}' ) . '</h2>' . $grid . '</section>';
}
